def has_duplicate_slow(nums):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] == nums[j]:
                return True
    return False

# O(n) time, O(n) space: remember what we have seen
def has_duplicate_fast(nums):
    seen = set()
    for x in nums:
        if x in seen:
            return True
        seen.add(x)
    return False

// O(n) time, O(n) space
static boolean hasDuplicate(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int x : nums) {
        if (!seen.add(x)) return true; // add returns false if already present
    }
    return false;
}

// O(n) time, O(n) space
bool hasDuplicate(const vector<int>& nums) {
    unordered_set<int> seen;
    for (int x : nums) {
        if (!seen.insert(x).second) return true; // second == false if already present
    }
    return false;
}

// Two pointers: while inside for, yet O(n) total
function longestRun(nums, limit) {
  let left = 0, sum = 0, best = 0;
  for (let right = 0; right < nums.length; right++) {
    sum += nums[right];
    while (sum > limit) sum -= nums[left++]; // left only moves forward
    best = Math.max(best, right - left + 1);
  }
  return best;
}

# Two pointers: while inside for, yet O(n) total
def longest_run(nums, limit):
    left = total = best = 0
    for right, x in enumerate(nums):
        total += x
        while total > limit:
            total -= nums[left]
            left += 1  # left only moves forward
        best = max(best, right - left + 1)
    return best
